#include <bits/stdc++.h>
using namespace std;

bool isPalindrome(const string& s) {
    int left = 0, right = (int)s.size() - 1;
    while (left < right) {
        if (s[left] != s[right]) return false;
        left++; right--;
    }
    return true;
}

string shortestPalindrome(string s) {
    int n = (int)s.size();
    for (int length = n; length > 0; length--) {
        string prefix = s.substr(0, length);
        if (isPalindrome(prefix)) {                                     // direct palindrome check for this candidate
            string suffixToAdd = s.substr(length);
            reverse(suffixToAdd.begin(), suffixToAdd.end());
            return suffixToAdd + s;
        }
    }
    if (s.empty()) return s;
    string reversed = s;
    reverse(reversed.begin(), reversed.end());
    return reversed + s;
}

int main() {
    string s = "aacecaaa";
    cout << shortestPalindrome(s) << endl;
    return 0;
}

