        String reversedS = new StringBuilder(s).reverse().toString();
        String combined = s + "#" + reversedS;
        int n = combined.length();
        int[] lps = new int[n];
        int length = 0, i = 1;
        while (i < n) {
            if (combined.charAt(i) == combined.charAt(length)) {
                length++;
                lps[i] = length;
                i++;
            } else if (length > 0) {
                length = lps[length - 1];
            } else {
                lps[i] = 0;
                i++;
            }
        }
        int palindromicPrefixLength = lps[n - 1];
        String suffixToAdd = new StringBuilder(s.substring(palindromicPrefixLength)).reverse().toString();
        return suffixToAdd + s;
    }

    public static void main(String[] args) {
        String s = "aacecaaa";
        Main solution = new Main();
        System.out.println(solution.shortestPalindrome(s));
    }
